    unsigned short newer;                       // +0x02
    long           lastUseTime;                 // +0x04
    unsigned long  glyphIndex : 24;             // +0x08
    unsigned long  loading    : 1;              // +0x0b bit 0
    unsigned long  cacheIndex;                  // +0x0c
