    unsigned long                 width;        // +0x00
    unsigned long                 height;       // +0x04
    unsigned long                 numEntries;   // +0x08
    unsigned long                 entryWidth;   // +0x0c
    unsigned long                 entryHeight;  // +0x10
    unsigned long                 entrySize;    // +0x14
